import sharp from "sharp";

// Marca de agua en el servidor (para re-sellar fotos ya subidas).
// Overlay DIAGONAL y tenue, pre-dibujado como PNG transparente (base64), así
// NO dependemos de fuentes del servidor (que faltan en el entorno serverless).
// Se ajusta al tamaño de la foto y se superpone una sola vez (no en mosaico),
// para lograr el mismo estilo diagonal del resto del catálogo.

const OVERLAY_B64 =
  "";
const OVERLAY = Buffer.from(OVERLAY_B64, "base64");

export { SELLO_VERSION } from "./sello-version";

export async function marcarAguaBuffer(input: Buffer): Promise<Buffer> {
  const img = sharp(input, { failOn: "none" }).rotate(); // respeta EXIF
  const meta = await img.metadata();
  const W = meta.width || 0;
  const H = meta.height || 0;
  if (!W || !H) throw new Error("Imagen sin dimensiones");

  const overlay = await sharp(OVERLAY).resize(W, H, { fit: "cover" }).png().toBuffer();

  return img
    .composite([{ input: overlay, blend: "over" }])
    .jpeg({ quality: 88 })
    .toBuffer();
}
